raph","content":[{"type":"text","text":"You may want to explore water heater replacement if:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your existing unit frequently needs repairs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your household or business regularly runs out of hot water"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The tank is leaking or showing signs of corrosion"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your water heater is no longer operating efficiently"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repair costs are becoming difficult to justify"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your hot water requirements have changed"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A plumbing professional can evaluate your current system, discuss suitable replacement options, and help you choose a water heater based on your hot water demand, available space, fuel type, and budget."}]},{"type":"paragraph","content":[{"type":"text","text":"Looking for water heater replacement in Denver or Boulder, CO? Submit your requirements to connect with a local professional."}]}]},"button":{"label":"Get Water Heater Replacement Help","href":"/book-service","variant":"primary"}}},{"id":"e3c1187c-a5e2-40d8-8d60-1efd0f81a1f5","type":"contentBlock","data":{"label":"3","heading":"Water Heater Installation","imagePosition":"none","image":"","imageAlt":"","content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Planning a new water heater installation for your home, rental property, office, or commercial building? The right system depends on your property's hot water needs, plumbing configuration, available utilities, and installation requirements."}]},{"type":"paragraph","content":[{"type":"text","text":"Professional water heater installation services may include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Installation of a new traditional tank water heater"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tankless water heater installation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replacement of an existing water heater"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hot water system installation for residential properties"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Water heater installation for commercial properties"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Connection and system setup"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Safety and operational checks"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recommendations for ongoing maintenance"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Proper installation is important for system performance, safety, and reliability. Gas, electrical, venting, and plumbing work should be handled by appropriately qualified professionals in accordance with applicable codes and permit requirements."}]},{"type":"paragraph","content":[{"type":"text","text":"If you are planning water heater installation in Denver or Boulder, share your project details to help find a professional who serves your location."}]}]},"button":{"label":"Request Water Heater Installation","href":"/book-service","variant":"primary"}}},{"id":"62f37f95-86d2-4b13-895c-cb3a831ae965","type":"contentBlock","data":{"label":"Residential Water Heater Services","heading":"Reliable Hot Water for Your Ho